import{r as e}from"./rolldown-runtime-hePW80VL.js";import{t}from"./jsx-runtime-NZYk81nU.js";var n=e(t()),r={title:`Fish Speech`,description:`The Fish Speech engine as implemented in Mizuoto's separate mizuoto-fishspeech distribution: S2 Pro's dual-AR transformer and the 44.1 kHz codec, Drama 3's mixture-of-experts backbone and codebook tower, what reproduces upstream exactly, one wait per frame and CUDA graphs, experts streamed by the row, the LoRA fine-tune, and parity results.`,icon:`Fish`},i={contents:[{heading:void 0,content:"Fish Audio S2 Pro and Drama 3 (fishaudio/fish-speech). S2 Pro and its port are under the Fish Audio Research License; Drama 3 and its port (`mizuoto_fishspeech/drama3`, ported from fish-speech 0f8a12e8) under the Fish Audio Community License 1.0 (see Drama 3). The ports are under these licences, so they ship as a distribution of its own, `mizuoto-fishspeech` (`packages/native/fishspeech`, package `mizuoto_fishspeech`, with `LICENSE.md` and `drama3/LICENSE.md`), registered under the entry-point group `mizuoto.engines` (`fishspeech = mizuoto_fishspeech:FishSpeechEngine`). Downloading the model and speaking need the licence accepted. On the CPU in fp32 with the same seed its codes and audio are identical to upstream's seeded `generate_long` as Mizuoto 0.1 ran it, and its trainer gives 0.1's exported model bit for bit. User-facing details: Engines in depth."},{heading:`variants-and-files`,content:"Two variants. `s2_pro` (catalogue model `fishspeech/s2-pro`, this page up to Drama 3): cloning from one to four clips, each with its transcript; inline tags; dialogue between speakers (`<|speaker:i|>`). The model folder holds `config.json`, the weights (`model.safetensors.index.json` and its shards, `model.safetensors`, or `model.pth`), `codec.pth` and the BPE tokenizer files. A voice's cache is `codes.pt`, each reference's codes."},{heading:`variants-and-files`,content:"Precision: bf16 on a CUDA GPU, as upstream; fp32 elsewhere (bf16 is emulated on a CPU and far slower); `engines.fishspeech.dtype` overrides."},{heading:`how-it-works`,content:"The prompt is a ChatML conversation: a system turn holding each reference's text and its codes, then the text to speak. The **slow transformer** (Qwen3-4B-shaped: 36 layers, q/k RMSNorm, one fused `wqkv`) generates a frame's semantic token; the **fast transformer** (4 layers) generates the other nine codebooks from the slow model's normed hidden state. The **codec** (a modified DAC at 44.1 kHz: causal convolutions, a windowed transformer, a downsampling residual quantiser with one semantic codebook of 4096 and nine of 1024; about 21.5 frames a second) encodes references and decodes frames into audio. Text is generated in batches of speaker turns, each batch decoded as it finishes."},{heading:`how-it-works`,content:`Module`},{heading:`how-it-works`,content:`What it is`},{heading:`how-it-works`,content:"`engine.py`"},{heading:`how-it-works`,content:"References read, resampled to 44.1 kHz and encoded; generation by batches of speaker turns; codec decoding; the `codec_encode` and `codec_decode` operations"},{heading:`how-it-works`,content:"`model.py`"},{heading:`how-it-works`,content:`The dual-AR transformer`},{heading:`how-it-works`,content:"`generate.py`"},{heading:`how-it-works`,content:"The conversation prompt, sampling in upstream's order, turn grouping, the decoder (`Decoder`) with its CUDA graphs"},{heading:`how-it-works`,content:"`fused.py`"},{heading:`how-it-works`,content:"`compute.compile`: the decoding step's pieces under `torch.compile` (`Fused`)"},{heading:`how-it-works`,content:"`codec.py`"},{heading:`how-it-works`,content:`The 44.1 kHz codec`},{heading:`how-it-works`,content:"`train.py`, `finetune.py`"},{heading:`how-it-works`,content:"`FishSpeechTrainer` (method `lora`) and its maths"},{heading:`how-it-works`,content:"Shared: `text/tokenize/bpe.py`, `runtime/lm/cache.py`, `runtime/graphs.py`, `nn/dsp/` (`resample`, `wav`, `flac`)."},{heading:`what-reproduces-upstream`,content:"**The prompt** is upstream's conversation, each text part tokenised alone; a frame's main token is `semantic_begin_id + code`."},{heading:`what-reproduces-upstream`,content:"**Sampling** draws from the request's generator in upstream's order: the main token twice (with the request's temperature and top-p, then with 1.0 and 0.9 for repetition-aware sampling), then nine fast-transformer draws. A draw is `argmax(probs / -log(u))`. Top-k is fixed at 30, as upstream fixes it."},{heading:`what-reproduces-upstream`,content:"**Numerics**: Fish's RMSNorm in float32; RoPE over adjacent pairs with the frequency table rounded to bfloat16; the prefill on SDPA with a boolean causal mask, decoding steps on SDPA's math kernel (called directly, no process-wide setting, with the boolean mask made additive first as `F.scaled_dot_product_attention` does: given a bool mask, the kernel itself adds it as numbers; until 0.2.6 every step's scores were shifted by 1, the same codes on the CPU but other bits, and on a GPU in bfloat16 another take); the fast transformer's hand-written softmax. Weight norm is kept in both checkpoint formats and recomputed every forward, as upstream does."},{heading:`what-reproduces-upstream`,content:`**References** are resampled with torchaudio's kernel to 44.1 kHz.`},{heading:`what-reproduces-upstream`,content:"**WAV output.** `codec_decode` writes WAV with `nn.dsp.wav.write_wav`, byte-identical to `soundfile.write`: libsndfile 1.2 stores `lrint(x × 2³¹) >> 16`, clipped, which is `floor(x × 32768)` except for values just below a step. `codec_encode` reads WAV only."},{heading:`deviations`,content:"**No daemon thread and no 32 768-position preallocated cache.** The cache grows by concatenation; after `repeat_interleave` the keys and values are the tensors upstream builds. Attention masks are made per call instead of upstream's 4 GiB of mask buffers."},{heading:`deviations`,content:"**A codec module upstream never runs is not built.** Upstream's codec builds a transformer for the decoder's first block but never attaches it (no weights, never run). `codec.pth` also holds RoPE tables and masks an older upstream saved, which upstream no longer loads; they are ignored."},{heading:`deviations`,content:"**Accepted, with no effect**: `normalize` and `repetition_penalty` reach nothing in upstream's inference path, so they do nothing here either."},{heading:`deviations`,content:"**References encode on a GPU.** Upstream loads the codec in bf16 on a GPU and `encode_reference` passes it float32 audio, so cloning there fails (`Input type (float) and bias type (c10::BFloat16) should be the same`; reproduced with 0.1 on an RTX 3090). The port casts the reference audio to the codec's precision; on the CPU, in fp32, nothing changes."},{heading:`deviations`,content:`**Snake on a GPU** is upstream's TorchScript function, computed as TorchScript computes it rather than as the same code run eagerly:`},{heading:`deviations`,content:"**Under autocast** (decoding in bf16 or fp16) it runs in float32 throughout. Eager autocast keeps `alpha · x` and the sine in the low precision; the port did so until mizuoto-fishspeech 0.3.3, and its decoded audio differed from upstream's by up to 0.036 on an RTX 3060."},{heading:`deviations`,content:`**Without autocast** (encoding references) the operations run in place, with the same result.`},{heading:`deviations`,content:"**Against upstream:** with TorchScript's fuser off, the port's codec gives upstream's reference codes and decoded audio bit for bit on an RTX 3060 in bf16 (Drama 3's `codec.pth`, which S2 Pro shares; three clips)."},{heading:`deviations`,content:`**Upstream's fused kernel:** from a shape's second call, upstream's TorchScript fuses Snake, which changes rounding and depends on what the process has already run. Against that, the decoded audio is within 0.01 and about a fifth of the reference codes differ. Computing Snake in float32 and rounding once, as the fused kernel does, still left 8–14 % of the codes different, so no fixed computation can follow it.`},{heading:`memory-and-speed`,content:"Phases: the codec encodes references and decodes each batch of frames; the language model (`kind=\"sequence\"`, the fast transformer `hot`) generates each batch, placed again as generation resumes. Each batch's working memory is the slow model's cache for its true bound: the references' codes, every text token, the frames of the batches before it and `max_new_tokens`, within `max_seq_len`. S2 Pro took 10.2 GB of GPU memory at most with the defaults (bf16; G13 on Performance); with less, the runtime streams part of its weights. If the codec's decoding runs out of memory with `compute.oom_fallback` on, its convolution decoder runs in tiles of 256 latent frames (about 3 s), each after the 20 frames its first sample depends on (the decoder is causal), and the quantizer's side whole: the whole's samples up to the sums' rounding (40 dB SNR in bf16 on a GPU, where bf16 against float32 is 37.9 dB), in 275 MB instead of 5 GB for 60 s."},{heading:`memory-and-speed`,content:"A frame is one slow-transformer step and ten codebooks. The plain loop waited for the device about 22 times a frame: the end-of-turn check; a masked assignment zeroing the codebook embeddings of non-semantic tokens (`vq_sum[~mask] = 0` reads the mask back); the fast transformer's mask and rotary rows taken with list indices (two copies to the device per codebook); a Python boolean stored into a device tensor in the sampler, twice per draw. Each became an exact equivalent (`torch.where`, slices, `fill_`), and the decoding step's mask is made as the one all-true row it is. One wait per frame remains."},{heading:`memory-and-speed`,content:"With `compute.cuda_graphs` (NVIDIA, the model wholly on its device) `generate.Decoder` keeps fixed tensors per loaded model: the slow step runs as one graph per stretch between attention calls (`LayerSteps`), and the frame's draws, repetition-aware sampling and the fast transformer as one graph. The sampling settings are device tensors filled per request, so one set of graphs serves every request. The codes are identical, 2.2–2.5 times faster per frame on the decode loop."},{heading:`memory-and-speed`,content:"On a free RTX 3060 the whole model's frame takes about 64 ms with graphs. About 50 ms of that is reading 16 GB of weights at close to the card's bandwidth; most of the rest is thousands of small kernels. `compute.compile` (opt-in, not exact; `fused.py`) fuses them: it compiles each layer's halves around its attention, the attention over the cache, the step's embeddings and heads, and the draws' probabilities, inside the same graphs, with the eager code untouched when it is off. Each frame is then 1.15 times faster. The draws are unchanged, but the probabilities differ in their last bits, so the speech is another take of the same text and voice, which still repeats under a seed and passes the contract suite. It runs only while the model is wholly on its device, and the output lists it (`applied[\"compile\"]`). Details: Acceleration."},{heading:`training`,content:"Method `lora` (stages `tokens`, `train`, `export`): upstream's `extract_vq`, `build_dataset`, its Lightning + Hydra `train.py` with loralib and `merge_lora`, without any of those libraries or protobuf. Seeded alike, it gives 0.1's codes, losses, LoRA weights and exported `model.pth` bit for bit on the CPU, and every other exported file byte for byte. (0.1 never seeded, so only its first step repeats.) It runs on every device kind."},{heading:`training`,content:"**Initialisation draws, jumped over.** Upstream builds the model with random weights before loading the checkpoint, and initialises each loralib layer twice before drawing `A`: some 18 G draws. `initial_lora` computes how far those draws advance the generator from the shapes alone (a float32 `normal_` or `uniform_` advances it by its size, `normal_` by 16 more when the size is not a multiple of 16) and jumps MT19937 ahead in GF(2) (`mizuoto.training.rng`): the same state in 2 s instead of 40 s of drawing, computed in a thread while the weights load. Then come the loader's base seed and each step's LoRA dropout masks."},{heading:`training`,content:`**Mixed precision as upstream's.** The checkpoint's tensors are assigned as upstream assigns them, so S2's norms stay bfloat16 while the LoRA layers hold float32 copies.`},{heading:`training`,content:"**Kept**: upstream's training forward does not scale the codebook embeddings by 1/√11 as inference does; the warm-up makes the first step's learning rate 0 and `B` starts at zero, so the first two steps give the same loss."},{heading:`training`,content:"**Padding.** The collator pads with `<|end_of_text|>`, which S2's vocabulary lacks: upstream pads with 0, and so does Mizuoto."},{heading:`training`,content:"**The export** is upstream's flat `dual_ar` form (`config.json` + `model.pth`), which both 0.1 and Mizuoto load. The final validation pass is skipped (it changes nothing that is kept)."},{heading:`training`,content:"`training.memory`: upstream's per-layer checkpointing stays as it is; under `bf16-true` the LoRA layers keep the checkpoint's own bfloat16 tensors as their frozen weights (memory-mapped from the safetensors files, no copy: the same values), and the export's key order is read from a model built on the meta device. Measured on S2 Pro (2026-10-19, an RTX 3090): the training stage's process holds 0.4 GB of its own memory while loading (8.9 GB with bfloat16 copies, 17 GB with float32 ones) and peaks at 5 GB resident; the export holds the merged weights, 9 GB, beside the mapped checkpoint (page cache). Under `lowest` the LoRA linear layers' frozen weights stay in page-locked RAM and are copied to the GPU for each product (`streamed_linear`, the model placed without them): identical (the tiny trainer's losses and LoRA weights on the CPU); S2 Pro's LoRA at batch 2 then peaks at 7.9 GB instead of 15.6 (an RTX 3060, 15.6 s a step there over its PCIe x4 link), and the default batch 4 is estimated at 12.6 GB."},{heading:`parity`,content:"Codes identical to upstream's seeded `generate_long` on the CPU in fp32; the tokenizer, the references' resampling and codes and the codec's decoding are identical too. Both stack cases (English and Chinese cloning) are identical sample for sample; two more cases load each implementation's export in the other, identical too. The contract suite passes (6 tests)."},{heading:`limitations`,content:`About 10 GB of GPU memory to run the model whole (S2 Pro); on a CPU it runs in fp32 and is slow.`},{heading:`limitations`,content:"`normalize` and `repetition_penalty` have no effect (as upstream), and top-k cannot be changed."},{heading:`limitations`,content:`Results are under the Fish Audio Research License: not for commercial use, and not for training other engines.`},{heading:`drama-3`,content:"Variant `drama3`, catalogue model `fishspeech/drama-3` (fishaudio/drama-3 at 78e5ab79, 41.5 GB: the weights with the experts in block FP8, and S2's `codec.pth`, byte for byte the same file). Ported from fish-speech 0f8a12e8 (`fish_speech/models/text2semantic/fish_omni` and `generate_long_drama3`), as `mizuoto_fishspeech/drama3`. It clones from one to four clips (each with its transcript), speaks without a reference in a voice of its own, takes inline directions (`[whispering]`, `[laughing]`, `<whisper>…</whisper>`) and up to sixteen speakers (`<|speaker:0|>`…`<|speaker:15|>`; a reference's transcript may start with its speaker's tag). Licence: the Fish Audio Community License 1.0, the variant's own (`variants.drama3.licence`); the engine's acceptance covers both licences, and its outputs are tagged `fish-audio-community`."},{heading:`how-it-works-1`,content:`Module`},{heading:`how-it-works-1`,content:`What it is`},{heading:`how-it-works-1`,content:"`drama3/config.py`"},{heading:`how-it-works-1`,content:"`config.json`: the backbone's text config, the tower's, the semantic band, checked as upstream checks them"},{heading:`how-it-works-1`,content:"`drama3/layers.py`"},{heading:`how-it-works-1`,content:`Zero-centred RMSNorm, partial RoPE (halves), gated softmax attention, Gated DeltaNet (a causal depthwise convolution, then the gated delta rule: by chunks of 64 for a prompt, token by token after)`},{heading:`how-it-works-1`,content:"`drama3/moe.py`"},{heading:`how-it-works-1`,content:`256 routed experts a layer (8 per token) and a gated shared expert; the experts stacked, kept in FP8, streamed by the row`},{heading:`how-it-works-1`,content:"`drama3/backbone.py`"},{heading:`how-it-works-1`,content:"Qwen3.5-MoE's hybrid text model (40 layers, every fourth softmax attention) and its `lm_head`; loading the per-expert FP8 tensors"},{heading:`how-it-works-1`,content:"`drama3/tower.py`"},{heading:`how-it-works-1`,content:`The codebook tower: 4 shared and 9 residual layers attending over the frames, each residual layer's head drawing the next code; both samplers`},{heading:`how-it-works-1`,content:"`drama3/prompt.py`"},{heading:`how-it-works-1`,content:"The prompt (a chat: system turn with `[Reference i]` blocks, earlier chunks as finished turns, the open voice turn), text checks, long-text chunks and their history"},{heading:`how-it-works-1`,content:"`drama3/generate.py`"},{heading:`how-it-works-1`,content:"Prefill in blocks of 128 rows (teacher-forcing the tower's caches), the decoding loop (`Decoder`), chunk after chunk"},{heading:`how-it-works-1`,content:"`drama3/steps.py`"},{heading:`how-it-works-1`,content:"The decoding step as CUDA graphs around its attention calls (`Stretches`), its fixed tensors"},{heading:`how-it-works-1`,content:"`drama3/engine.py`"},{heading:`how-it-works-1`,content:"`LoadedDrama3`: S2's codec, references and operations (it subclasses `LoadedFishSpeech`) with the backbone and tower"},{heading:`how-it-works-1`,content:"A frame is ten codes: the backbone predicts its main token (the end of the turn or a semantic token, whose place in the band is code 0) from the frames so far, each prompt row's embedding being its token's plus, for audio rows, its code 1 (scaled by 1/√2). The tower then takes the backbone's hidden state and draws codes 1–9, one residual layer per code, its first shared layer also seeing the previous frame's codes 2–9. Text is cut into chunks of about 300 UTF-8 bytes with at most three speakers each (sentence ends, then clause marks, then spaces; never inside a tag or bracket), each generated with the first chunk and the latest one in its prompt as history; `single_chunk` generates the whole text at once."},{heading:`what-reproduces-upstream-1`,content:`On the CPU, upstream's modules and the port give the same hidden states, logits, frames and audio, bit for bit and sample for sample (see Parity). In particular:`},{heading:`what-reproduces-upstream-1`,content:"**Every operation in upstream's order**: the norms in float32, the rotary tables computed per call, the delta rule's chunked form for prompts (`solve_triangular` per chunk) and its recurrence for steps, the GQA attention (a single query row folds each key head's query heads into rows; more rows repeat the key heads) through `mizuoto.runtime.accel.attention` with SDPA and a boolean mask, the tower's interleaved RoPE, its float32-output down projection for float16; in float16 the experts are dequantized in float32 and saturated to float16's range before the cast, as upstream's dense experts are."},{heading:`what-reproduces-upstream-1`,content:"**The experts**: up to 64 (token, expert) pairs in one batched matmul over the gathered experts (a decoding step), more expert by expert, summed in float32 by `index_add_` in the experts' order (a prompt): the two paths give different bits, so both are kept. The router's softmax and top-k in float32, the weights renormalised."},{heading:`what-reproduces-upstream-1`,content:`**The prompt**, each literal tokenised alone, references checked and tagged as upstream tags them; the chunking (upstream's tests' cases are the package's tests) and the history (the first chunk pinned, the latest one, dropped oldest first when the prompt passes 8192 rows).`},{heading:`what-reproduces-upstream-1`,content:"**Sampling** draws from the request's generator in upstream's order: per frame, the main token twice (at the request's settings over the end and the semantic band, then at 1.0, top-k 30, top-p 0.95; the second replaces the first when the first is an audio token among the last 16 main tokens), then the nine codes. A draw is `argmax(p / E)` with `E ~ Exp(1)`. The `sampler` option selects Fish Audio's reference sampler (`reference_argmax` / `reference_ras`, upstream's `--reference-sampling`): an epsilon cutoff for the main token (`epsilon_cutoff`, 0.001 by default), every repeated main token replaced (the end included), the codes drawn only from the codec's 1024."},{heading:`what-reproduces-upstream-1`,content:"**Upstream's limits**: at most 8192 prompt rows and 10 240 rows in all (its CUDA graphs' capacity; a chunk's frames are clamped to what is left), the defaults of Fish Audio's SDK (temperature 0.7, top-p 0.7, top-k 30, 1024 frames per chunk; `max_new_tokens = 0`: 600, or 2048 with `single_chunk`)."},{heading:`what-reproduces-upstream-1`,content:"**The codec**: S2's, its weight norm folded once in float32 before the cast to the model's precision (upstream's `load_codec_model` for Drama 3), decoding under autocast in that precision; references encoded in it."},{heading:`cuda-graphs`,content:"With `compute.cuda_graphs` (an NVIDIA GPU holding the backbone and the tower whole: about 44 GB in bfloat16) the decoding step runs as CUDA graphs that replay the eager kernels (`drama3/steps.py`, `generate.Decoder`). A step is the tower's graphs (the output head, the frame's draws, one graph between each two of its 13 layers' attention calls), then the backbone's on that frame (one graph between each two of its 10 softmax attention layers, the Gated DeltaNet layers, the router and the experts inside them). The attention calls run eagerly between the graphs, over caches that grow by one each step, so the caches and the attention kernels are the eager code's. The step waits for the device once, for the frame's main token and whether its logits were finite."},{heading:`cuda-graphs`,content:`**Fixed tensors**, kept with the loaded model: the step's inputs and outputs (the last hidden state, the position, the previous frame, the last 16 main tokens padded with −1, the frame and its flags) and the Gated DeltaNet layers' states, which the graphs update in place and each request starts at zero. The attention layers' caches stay each request's own.`},{heading:`cuda-graphs`,content:`**The sampling settings are captured as the eager code passes them**, as Python numbers: CUDA divides by a number as a multiplication by its reciprocal and by a device tensor as a true division, so tensors would change bits. The tower's graphs (14 captures) are captured again when a request's temperature, top-p, top-k, sampler or cutoff differs; the backbone's are kept.`},{heading:`cuda-graphs`,content:`**Upstream's own graphs are not ported**: they capture the whole step for a few cache lengths (1024, 2048, 4096, 10 240), attending over a padded, masked cache with the settings as device tensors, which changes bits against its eager decoding.`},{heading:`cuda-graphs`,content:`**Streamed experts decode eagerly**: on a GPU smaller than the model the experts stream by the row, and which rows a step copies is learnt from the device, which a graph cannot wait for.`},{heading:`cuda-graphs`,content:"Checked on the CPU through `Graphs`' contract (each stretch warmed up and captured with its state put back, then replayed): the eager audio for both samplers, several chunks, later requests and changed settings (`test_the_step_as_graph_stretches_decodes_exactly_as_eagerly`). On an NVIDIA GPU, `test_cuda_graphs_decode_exactly_as_eagerly_on_a_gpu` (bfloat16 and float16) and `test_a_failed_capture_falls_back_to_the_same_audio_on_a_gpu` compare graphs with eager decoding on the tiny model; they skip without one."},{heading:`deviations-1`,content:`**Devices and precision.** Upstream runs Drama 3 only on NVIDIA GPUs, in bfloat16 (float16 before SM80, with a float32 residual stream); its entry points refuse the CPU and float32. The port runs on every device kind, in float32 on the CPU (as S2 Pro): the reference it is checked against is upstream's modules run there in float32, unchanged.`},{heading:`deviations-1`,content:`**The experts stay in FP8**, the experts a call uses dequantized as it runs, as upstream does wherever its FP8 kernel does not run; upstream's other path dequantizes them all at load. Both give the same values (the tiny parity checks both against the port): 32 GB of experts instead of 64 GB in bfloat16 or 129 GB in float32. **Upstream's W8A8 kernel** (Triton, SM89 and newer, which also quantizes the activations to FP8) is not ported: its results differ, so it could only come as an opt-in, and it cannot be measured here.`},{heading:`deviations-1`,content:`**No multi-GPU layer split and no cache kept between requests.** Upstream spreads the layers over up to four GPUs and keeps caches sized for the largest request so far; here the model manager places the layers (streaming what does not fit) and each request has its own caches. Attention reads only the attended prefix either way.`},{heading:`deviations-1`,content:`**Non-finite logits** are refused, as upstream refuses them, but checked once per frame (at the frame's one wait for the device) rather than before each draw.`},{heading:`deviations-1`,content:"**The audio is the chunks' audio joined**, unclipped, as upstream's; S2 Pro's engine clips each batch. The variant declares `long_text`, so Mizuoto hands the engine the whole text and upstream's chunking and history apply (cut by Mizuoto into separate requests, the history would never cross them)."},{heading:`deviations-1`,content:"**What Mizuoto does before any engine** applies here too: the text and each reference's transcript are stripped of surrounding white space; a reference is stored in the voice library as mono 16-bit WAV (a float, 24-bit or stereo clip is converted, so its codes can differ from upstream reading the original file); one longer than 30 s is trimmed under `tts.reference_policy`; seeds are not negative (upstream takes the absolute value)."},{heading:`deviations-1`,content:`**Not ported**: upstream's CUDA graphs for Drama 3 (they change bits; Mizuoto's replay the eager kernels, see CUDA graphs), its fine-tuning (upstream removed its training code with Drama 3, so the LoRA method is S2 Pro's only), and "director revision" across turns (not in the open code).`},{heading:`memory-and-speed-1`,content:"Handles: the backbone (`kind=\"sequence\"`; each layer two units, its attention `hot` and its MoE, and the output head `hot`), the tower (`sequence`) and the codec. The experts stream **by the row** (Development: memory): a layer whose MoE unit is not resident keeps its 256 experts in pinned host memory and each call copies the experts its tokens are routed to (a decoding step: 8 a layer, about 25 MB; a prompt block: expert by expert), so a GPU far smaller than the model runs it. Whole, the model needs about 44 GB; its dense part (attention, shared experts, embeddings and head, the tower) is about 7.5 GB in bfloat16. Working memory per request: the softmax layers' and the tower's caches for the request's rows (at most 10 240), the DeltaNet states, a prompt block's activations and the experts a step dequantizes."},{heading:`memory-and-speed-1`,content:"On the CPU, in float32 with 16 threads, a frame takes about 2.1 s, upstream's modules as long (a second of speech is 21.5 frames: some 45 s of compute); a prompt of 230 rows about 35 s. On a GPU it needs about 44 GB to hold the whole model, or its experts (30 GiB) stream from RAM; where RAM cannot hold them either, the layers' experts that do not fit are kept in files (`runtime.filemap`, Memory). First run on a GPU, 2026-11-05: an RTX 3060 (12 GB, PCIe x4) in a machine with 31 GB of RAM, bf16: 9.1 GB on the GPU, 17.0 GB of experts in page-locked RAM, 20.7 GB in files; a warm request of 5.5–8.3 s of speech took 128–162 s (176–226 GB copied to the GPU a request, 1.4 GB/s), its two runs identical; 15–32 GiB of it read from the disk, the rest of the file-backed experts from the page cache (72–87 %); RAM never fell below 7.9 GB available."},{heading:`memory-and-speed-1`,content:`A random model with the real one's shapes but 8 experts did run, on an RTX 3060 (2026-11-03, torch 2.8, bf16, 8.5 GB on the device). Every token still uses 8 experts, so a decoding step does the real model's work.`},{heading:`memory-and-speed-1`,content:`**Speed:** 150 frames took 19.2 s eagerly and 16.3 s with CUDA graphs, ×1.18 (128 → 109 ms a frame), identical audio.`},{heading:`memory-and-speed-1`,content:`**Graphed frames:** about 7,250 kernels each, the device busy 97 % of the time.`},{heading:`memory-and-speed-1`,content:`**The tiny test model:** ×2.1 (1.56 → 0.74 s a request), identical too.`},{heading:`parity-1`,content:"Against upstream's own modules (fish-speech 0f8a12e8) on the CPU in float32, the same seed and thread count, with the real model (2026-11-01; workspace `experiment/fish-drama3`, `scripts/real_upstream.py`, `real_native.py`, `real_compare.py`): seven cases, the reference clips' codes, every chunk's codes and the audio **identical** sample for sample: English and Chinese cloning, no reference, inline tags (`[laughing]`, `[whispering]`), a two-speaker dialogue with two references, the reference sampler (`reference_ras`, cutoff 0.002), and a long text generated as two chunks with history (542 frames, 25 s). Upstream repeated itself exactly before being compared. Upstream ran as its `TTSInferenceEngine` runs a request (references through its loader and codec, `set_seed`, `generate_long_drama3`, its codec's decoding), the port as the server runs it (`synthesize`). On a tiny random model (`scripts/tiny_parity.py`) twelve cases more (no cap on top-k, top-k 10 at temperature 1.2, single chunk, `max_new_tokens = 0`, Chinese with paired tags…) are identical in float32 and bfloat16, against upstream's FP8 experts and its dequantized ones, with the backbone's hidden states and logits bit for bit."},{heading:`parity-1`,content:"A source review against upstream found Mizuoto cutting Drama 3's long text itself (fixed: the variant declares `long_text`) and float16's experts unclamped (fixed), and the request-level differences listed under Deviations."}],headings:[{id:`variants-and-files`,content:`Variants and files`},{id:`how-it-works`,content:`How it works`},{id:`what-reproduces-upstream`,content:`What reproduces upstream`},{id:`deviations`,content:`Deviations`},{id:`memory-and-speed`,content:`Memory and speed`},{id:`training`,content:`Training`},{id:`parity`,content:`Parity`},{id:`limitations`,content:`Limitations`},{id:`drama-3`,content:`Drama 3`},{id:`how-it-works-1`,content:`How it works`},{id:`what-reproduces-upstream-1`,content:`What reproduces upstream`},{id:`cuda-graphs`,content:`CUDA graphs`},{id:`deviations-1`,content:`Deviations`},{id:`memory-and-speed-1`,content:`Memory and speed`},{id:`parity-1`,content:`Parity`}]},a=[{depth:2,url:`#variants-and-files`,title:(0,n.jsx)(n.Fragment,{children:`Variants and files`})},{depth:2,url:`#how-it-works`,title:(0,n.jsx)(n.Fragment,{children:`How it works`})},{depth:2,url:`#what-reproduces-upstream`,title:(0,n.jsx)(n.Fragment,{children:`What reproduces upstream`})},{depth:2,url:`#deviations`,title:(0,n.jsx)(n.Fragment,{children:`Deviations`})},{depth:2,url:`#memory-and-speed`,title:(0,n.jsx)(n.Fragment,{children:`Memory and speed`})},{depth:2,url:`#training`,title:(0,n.jsx)(n.Fragment,{children:`Training`})},{depth:2,url:`#parity`,title:(0,n.jsx)(n.Fragment,{children:`Parity`})},{depth:2,url:`#limitations`,title:(0,n.jsx)(n.Fragment,{children:`Limitations`})},{depth:2,url:`#drama-3`,title:(0,n.jsx)(n.Fragment,{children:`Drama 3`})},{depth:3,url:`#how-it-works-1`,title:(0,n.jsx)(n.Fragment,{children:`How it works`})},{depth:3,url:`#what-reproduces-upstream-1`,title:(0,n.jsx)(n.Fragment,{children:`What reproduces upstream`})},{depth:3,url:`#cuda-graphs`,title:(0,n.jsx)(n.Fragment,{children:`CUDA graphs`})},{depth:3,url:`#deviations-1`,title:(0,n.jsx)(n.Fragment,{children:`Deviations`})},{depth:3,url:`#memory-and-speed-1`,title:(0,n.jsx)(n.Fragment,{children:`Memory and speed`})},{depth:3,url:`#parity-1`,title:(0,n.jsx)(n.Fragment,{children:`Parity`})}];function o(e){let t={a:`a`,code:`code`,h2:`h2`,h3:`h3`,li:`li`,p:`p`,strong:`strong`,table:`table`,tbody:`tbody`,td:`td`,th:`th`,thead:`thead`,tr:`tr`,ul:`ul`,...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsxs)(t.p,{children:[`Fish Audio S2 Pro and Drama 3 (`,(0,n.jsx)(t.a,{href:`https://github.com/fishaudio/fish-speech`,children:`fishaudio/fish-speech`}),`). S2 Pro and its port are under the Fish Audio Research License; Drama 3 and its port (`,(0,n.jsx)(t.code,{children:`mizuoto_fishspeech/drama3`}),`, ported from fish-speech 0f8a12e8) under the Fish Audio Community License 1.0 (see `,(0,n.jsx)(t.a,{href:`#drama-3`,children:`Drama 3`}),`). The ports are under these licences, so they ship as a distribution of its own, `,(0,n.jsx)(t.code,{children:`mizuoto-fishspeech`}),` (`,(0,n.jsx)(t.code,{children:`packages/native/fishspeech`}),`, package `,(0,n.jsx)(t.code,{children:`mizuoto_fishspeech`}),`, with `,(0,n.jsx)(t.code,{children:`LICENSE.md`}),` and `,(0,n.jsx)(t.code,{children:`drama3/LICENSE.md`}),`), registered under the entry-point group `,(0,n.jsx)(t.code,{children:`mizuoto.engines`}),` (`,(0,n.jsx)(t.code,{children:`fishspeech = mizuoto_fishspeech:FishSpeechEngine`}),`). Downloading the model and speaking need the licence accepted. On the CPU in fp32 with the same seed its codes and audio are identical to upstream's seeded `,(0,n.jsx)(t.code,{children:`generate_long`}),` as Mizuoto 0.1 ran it, and its trainer gives 0.1's exported model bit for bit. User-facing details: `,(0,n.jsx)(t.a,{href:`/docs/advanced-engines#fish-speech`,children:`Engines in depth`}),`.`]}),`
`,(0,n.jsx)(t.h2,{id:`variants-and-files`,children:`Variants and files`}),`
`,(0,n.jsxs)(t.p,{children:[`Two variants. `,(0,n.jsx)(t.code,{children:`s2_pro`}),` (catalogue model `,(0,n.jsx)(t.code,{children:`fishspeech/s2-pro`}),`, this page up to `,(0,n.jsx)(t.a,{href:`#drama-3`,children:`Drama 3`}),`): cloning from one to four clips, each with its transcript; inline tags; dialogue between speakers (`,(0,n.jsx)(t.code,{children:`<|speaker:i|>`}),`). The model folder holds `,(0,n.jsx)(t.code,{children:`config.json`}),`, the weights (`,(0,n.jsx)(t.code,{children:`model.safetensors.index.json`}),` and its shards, `,(0,n.jsx)(t.code,{children:`model.safetensors`}),`, or `,(0,n.jsx)(t.code,{children:`model.pth`}),`), `,(0,n.jsx)(t.code,{children:`codec.pth`}),` and the BPE tokenizer files. A voice's cache is `,(0,n.jsx)(t.code,{children:`codes.pt`}),`, each reference's codes.`]}),`
`,(0,n.jsxs)(t.p,{children:[`Precision: bf16 on a CUDA GPU, as upstream; fp32 elsewhere (bf16 is emulated on a CPU and far slower); `,(0,n.jsx)(t.code,{children:`engines.fishspeech.dtype`}),` overrides.`]}),`
`,(0,n.jsx)(t.h2,{id:`how-it-works`,children:`How it works`}),`
`,(0,n.jsxs)(t.p,{children:[`The prompt is a ChatML conversation: a system turn holding each reference's text and its codes, then the text to speak. The `,(0,n.jsx)(t.strong,{children:`slow transformer`}),` (Qwen3-4B-shaped: 36 layers, q/k RMSNorm, one fused `,(0,n.jsx)(t.code,{children:`wqkv`}),`) generates a frame's semantic token; the `,(0,n.jsx)(t.strong,{children:`fast transformer`}),` (4 layers) generates the other nine codebooks from the slow model's normed hidden state. The `,(0,n.jsx)(t.strong,{children:`codec`}),` (a modified DAC at 44.1 kHz: causal convolutions, a windowed transformer, a downsampling residual quantiser with one semantic codebook of 4096 and nine of 1024; about 21.5 frames a second) encodes references and decodes frames into audio. Text is generated in batches of speaker turns, each batch decoded as it finishes.`]}),`
`,(0,n.jsxs)(t.table,{children:[(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{children:`Module`}),(0,n.jsx)(t.th,{children:`What it is`})]})}),(0,n.jsxs)(t.tbody,{children:[(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`engine.py`})}),(0,n.jsxs)(t.td,{children:[`References read, resampled to 44.1 kHz and encoded; generation by batches of speaker turns; codec decoding; the `,(0,n.jsx)(t.code,{children:`codec_encode`}),` and `,(0,n.jsx)(t.code,{children:`codec_decode`}),` operations`]})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`model.py`})}),(0,n.jsx)(t.td,{children:`The dual-AR transformer`})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`generate.py`})}),(0,n.jsxs)(t.td,{children:[`The conversation prompt, sampling in upstream's order, turn grouping, the decoder (`,(0,n.jsx)(t.code,{children:`Decoder`}),`) with its CUDA graphs`]})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`fused.py`})}),(0,n.jsxs)(t.td,{children:[(0,n.jsx)(t.code,{children:`compute.compile`}),`: the decoding step's pieces under `,(0,n.jsx)(t.code,{children:`torch.compile`}),` (`,(0,n.jsx)(t.code,{children:`Fused`}),`)`]})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`codec.py`})}),(0,n.jsx)(t.td,{children:`The 44.1 kHz codec`})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsxs)(t.td,{children:[(0,n.jsx)(t.code,{children:`train.py`}),`, `,(0,n.jsx)(t.code,{children:`finetune.py`})]}),(0,n.jsxs)(t.td,{children:[(0,n.jsx)(t.code,{children:`FishSpeechTrainer`}),` (method `,(0,n.jsx)(t.code,{children:`lora`}),`) and its maths`]})]})]})]}),`
`,(0,n.jsxs)(t.p,{children:[`Shared: `,(0,n.jsx)(t.code,{children:`text/tokenize/bpe.py`}),`, `,(0,n.jsx)(t.code,{children:`runtime/lm/cache.py`}),`, `,(0,n.jsx)(t.code,{children:`runtime/graphs.py`}),`, `,(0,n.jsx)(t.code,{children:`nn/dsp/`}),` (`,(0,n.jsx)(t.code,{children:`resample`}),`, `,(0,n.jsx)(t.code,{children:`wav`}),`, `,(0,n.jsx)(t.code,{children:`flac`}),`).`]}),`
`,(0,n.jsx)(t.h2,{id:`what-reproduces-upstream`,children:`What reproduces upstream`}),`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The prompt`}),` is upstream's conversation, each text part tokenised alone; a frame's main token is `,(0,n.jsx)(t.code,{children:`semantic_begin_id + code`}),`.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Sampling`}),` draws from the request's generator in upstream's order: the main token twice (with the request's temperature and top-p, then with 1.0 and 0.9 for repetition-aware sampling), then nine fast-transformer draws. A draw is `,(0,n.jsx)(t.code,{children:`argmax(probs / -log(u))`}),`. Top-k is fixed at 30, as upstream fixes it.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Numerics`}),`: Fish's RMSNorm in float32; RoPE over adjacent pairs with the frequency table rounded to bfloat16; the prefill on SDPA with a boolean causal mask, decoding steps on SDPA's math kernel (called directly, no process-wide setting, with the boolean mask made additive first as `,(0,n.jsx)(t.code,{children:`F.scaled_dot_product_attention`}),` does: given a bool mask, the kernel itself adds it as numbers; until 0.2.6 every step's scores were shifted by 1, the same codes on the CPU but other bits, and on a GPU in bfloat16 another take); the fast transformer's hand-written softmax. Weight norm is kept in both checkpoint formats and recomputed every forward, as upstream does.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`References`}),` are resampled with torchaudio's kernel to 44.1 kHz.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`WAV output.`}),` `,(0,n.jsx)(t.code,{children:`codec_decode`}),` writes WAV with `,(0,n.jsx)(t.code,{children:`nn.dsp.wav.write_wav`}),`, byte-identical to `,(0,n.jsx)(t.code,{children:`soundfile.write`}),`: libsndfile 1.2 stores `,(0,n.jsx)(t.code,{children:`lrint(x × 2³¹) >> 16`}),`, clipped, which is `,(0,n.jsx)(t.code,{children:`floor(x × 32768)`}),` except for values just below a step. `,(0,n.jsx)(t.code,{children:`codec_encode`}),` reads WAV only.`]}),`
`]}),`
`,(0,n.jsx)(t.h2,{id:`deviations`,children:`Deviations`}),`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`No daemon thread and no 32 768-position preallocated cache.`}),` The cache grows by concatenation; after `,(0,n.jsx)(t.code,{children:`repeat_interleave`}),` the keys and values are the tensors upstream builds. Attention masks are made per call instead of upstream's 4 GiB of mask buffers.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`A codec module upstream never runs is not built.`}),` Upstream's codec builds a transformer for the decoder's first block but never attaches it (no weights, never run). `,(0,n.jsx)(t.code,{children:`codec.pth`}),` also holds RoPE tables and masks an older upstream saved, which upstream no longer loads; they are ignored.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Accepted, with no effect`}),`: `,(0,n.jsx)(t.code,{children:`normalize`}),` and `,(0,n.jsx)(t.code,{children:`repetition_penalty`}),` reach nothing in upstream's inference path, so they do nothing here either.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`References encode on a GPU.`}),` Upstream loads the codec in bf16 on a GPU and `,(0,n.jsx)(t.code,{children:`encode_reference`}),` passes it float32 audio, so cloning there fails (`,(0,n.jsx)(t.code,{children:`Input type (float) and bias type (c10::BFloat16) should be the same`}),`; reproduced with 0.1 on an RTX 3090). The port casts the reference audio to the codec's precision; on the CPU, in fp32, nothing changes.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Snake on a GPU`}),` is upstream's TorchScript function, computed as TorchScript computes it rather than as the same code run eagerly:`,`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Under autocast`}),` (decoding in bf16 or fp16) it runs in float32 throughout. Eager autocast keeps `,(0,n.jsx)(t.code,{children:`alpha · x`}),` and the sine in the low precision; the port did so until mizuoto-fishspeech 0.3.3, and its decoded audio differed from upstream's by up to 0.036 on an RTX 3060.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Without autocast`}),` (encoding references) the operations run in place, with the same result.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Against upstream:`}),` with TorchScript's fuser off, the port's codec gives upstream's reference codes and decoded audio bit for bit on an RTX 3060 in bf16 (Drama 3's `,(0,n.jsx)(t.code,{children:`codec.pth`}),`, which S2 Pro shares; three clips).`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Upstream's fused kernel:`}),` from a shape's second call, upstream's TorchScript fuses Snake, which changes rounding and depends on what the process has already run. Against that, the decoded audio is within 0.01 and about a fifth of the reference codes differ. Computing Snake in float32 and rounding once, as the fused kernel does, still left 8–14 % of the codes different, so no fixed computation can follow it.`]}),`
`]}),`
`]}),`
`]}),`
`,(0,n.jsx)(t.h2,{id:`memory-and-speed`,children:`Memory and speed`}),`
`,(0,n.jsxs)(t.p,{children:[`Phases: the codec encodes references and decodes each batch of frames; the language model (`,(0,n.jsx)(t.code,{children:`kind="sequence"`}),`, the fast transformer `,(0,n.jsx)(t.code,{children:`hot`}),`) generates each batch, placed again as generation resumes. Each batch's working memory is the slow model's cache for its true bound: the references' codes, every text token, the frames of the batches before it and `,(0,n.jsx)(t.code,{children:`max_new_tokens`}),`, within `,(0,n.jsx)(t.code,{children:`max_seq_len`}),`. S2 Pro took 10.2 GB of GPU memory at most with the defaults (bf16; G13 on `,(0,n.jsx)(t.a,{href:`/docs/development-performance`,children:`Performance`}),`); with less, the runtime streams part of its weights. If the codec's decoding runs out of memory with `,(0,n.jsx)(t.code,{children:`compute.oom_fallback`}),` on, its convolution decoder runs in tiles of 256 latent frames (about 3 s), each after the 20 frames its first sample depends on (the decoder is causal), and the quantizer's side whole: the whole's samples up to the sums' rounding (40 dB SNR in bf16 on a GPU, where bf16 against float32 is 37.9 dB), in 275 MB instead of 5 GB for 60 s.`]}),`
`,(0,n.jsxs)(t.p,{children:[`A frame is one slow-transformer step and ten codebooks. The plain loop waited for the device about 22 times a frame: the end-of-turn check; a masked assignment zeroing the codebook embeddings of non-semantic tokens (`,(0,n.jsx)(t.code,{children:`vq_sum[~mask] = 0`}),` reads the mask back); the fast transformer's mask and rotary rows taken with list indices (two copies to the device per codebook); a Python boolean stored into a device tensor in the sampler, twice per draw. Each became an exact equivalent (`,(0,n.jsx)(t.code,{children:`torch.where`}),`, slices, `,(0,n.jsx)(t.code,{children:`fill_`}),`), and the decoding step's mask is made as the one all-true row it is. One wait per frame remains.`]}),`
`,(0,n.jsxs)(t.p,{children:[`With `,(0,n.jsx)(t.code,{children:`compute.cuda_graphs`}),` (NVIDIA, the model wholly on its device) `,(0,n.jsx)(t.code,{children:`generate.Decoder`}),` keeps fixed tensors per loaded model: the slow step runs as one graph per stretch between attention calls (`,(0,n.jsx)(t.code,{children:`LayerSteps`}),`), and the frame's draws, repetition-aware sampling and the fast transformer as one graph. The sampling settings are device tensors filled per request, so one set of graphs serves every request. The codes are identical, 2.2–2.5 times faster per frame on the decode loop.`]}),`
`,(0,n.jsxs)(t.p,{children:[`On a free RTX 3060 the whole model's frame takes about 64 ms with graphs. About 50 ms of that is reading 16 GB of weights at close to the card's bandwidth; most of the rest is thousands of small kernels. `,(0,n.jsx)(t.code,{children:`compute.compile`}),` (opt-in, not exact; `,(0,n.jsx)(t.code,{children:`fused.py`}),`) fuses them: it compiles each layer's halves around its attention, the attention over the cache, the step's embeddings and heads, and the draws' probabilities, inside the same graphs, with the eager code untouched when it is off. Each frame is then 1.15 times faster. The draws are unchanged, but the probabilities differ in their last bits, so the speech is another take of the same text and voice, which still repeats under a seed and passes the contract suite. It runs only while the model is wholly on its device, and the output lists it (`,(0,n.jsx)(t.code,{children:`applied["compile"]`}),`). Details: `,(0,n.jsx)(t.a,{href:`/docs/development-acceleration#torchcompile-computecompile`,children:`Acceleration`}),`.`]}),`
`,(0,n.jsx)(t.h2,{id:`training`,children:`Training`}),`
`,(0,n.jsxs)(t.p,{children:[`Method `,(0,n.jsx)(t.code,{children:`lora`}),` (stages `,(0,n.jsx)(t.code,{children:`tokens`}),`, `,(0,n.jsx)(t.code,{children:`train`}),`, `,(0,n.jsx)(t.code,{children:`export`}),`): upstream's `,(0,n.jsx)(t.code,{children:`extract_vq`}),`, `,(0,n.jsx)(t.code,{children:`build_dataset`}),`, its Lightning + Hydra `,(0,n.jsx)(t.code,{children:`train.py`}),` with loralib and `,(0,n.jsx)(t.code,{children:`merge_lora`}),`, without any of those libraries or protobuf. Seeded alike, it gives 0.1's codes, losses, LoRA weights and exported `,(0,n.jsx)(t.code,{children:`model.pth`}),` bit for bit on the CPU, and every other exported file byte for byte. (0.1 never seeded, so only its first step repeats.) It runs on every device kind.`]}),`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Initialisation draws, jumped over.`}),` Upstream builds the model with random weights before loading the checkpoint, and initialises each loralib layer twice before drawing `,(0,n.jsx)(t.code,{children:`A`}),`: some 18 G draws. `,(0,n.jsx)(t.code,{children:`initial_lora`}),` computes how far those draws advance the generator from the shapes alone (a float32 `,(0,n.jsx)(t.code,{children:`normal_`}),` or `,(0,n.jsx)(t.code,{children:`uniform_`}),` advances it by its size, `,(0,n.jsx)(t.code,{children:`normal_`}),` by 16 more when the size is not a multiple of 16) and jumps MT19937 ahead in GF(2) (`,(0,n.jsx)(t.code,{children:`mizuoto.training.rng`}),`): the same state in 2 s instead of 40 s of drawing, computed in a thread while the weights load. Then come the loader's base seed and each step's LoRA dropout masks.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Mixed precision as upstream's.`}),` The checkpoint's tensors are assigned as upstream assigns them, so S2's norms stay bfloat16 while the LoRA layers hold float32 copies.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Kept`}),`: upstream's training forward does not scale the codebook embeddings by 1/√11 as inference does; the warm-up makes the first step's learning rate 0 and `,(0,n.jsx)(t.code,{children:`B`}),` starts at zero, so the first two steps give the same loss.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Padding.`}),` The collator pads with `,(0,n.jsx)(t.code,{children:`<|end_of_text|>`}),`, which S2's vocabulary lacks: upstream pads with 0, and so does Mizuoto.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The export`}),` is upstream's flat `,(0,n.jsx)(t.code,{children:`dual_ar`}),` form (`,(0,n.jsx)(t.code,{children:`config.json`}),` + `,(0,n.jsx)(t.code,{children:`model.pth`}),`), which both 0.1 and Mizuoto load. The final validation pass is skipped (it changes nothing that is kept).`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.code,{children:`training.memory`}),`: upstream's per-layer checkpointing stays as it is; under `,(0,n.jsx)(t.code,{children:`bf16-true`}),` the LoRA layers keep the checkpoint's own bfloat16 tensors as their frozen weights (memory-mapped from the safetensors files, no copy: the same values), and the export's key order is read from a model built on the meta device. Measured on S2 Pro (2026-10-19, an RTX 3090): the training stage's process holds 0.4 GB of its own memory while loading (8.9 GB with bfloat16 copies, 17 GB with float32 ones) and peaks at 5 GB resident; the export holds the merged weights, 9 GB, beside the mapped checkpoint (page cache). Under `,(0,n.jsx)(t.code,{children:`lowest`}),` the LoRA linear layers' frozen weights stay in page-locked RAM and are copied to the GPU for each product (`,(0,n.jsx)(t.code,{children:`streamed_linear`}),`, the model placed without them): identical (the tiny trainer's losses and LoRA weights on the CPU); S2 Pro's LoRA at batch 2 then peaks at 7.9 GB instead of 15.6 (an RTX 3060, 15.6 s a step there over its PCIe x4 link), and the default batch 4 is estimated at 12.6 GB.`]}),`
`]}),`
`,(0,n.jsx)(t.h2,{id:`parity`,children:`Parity`}),`
`,(0,n.jsxs)(t.p,{children:[`Codes identical to upstream's seeded `,(0,n.jsx)(t.code,{children:`generate_long`}),` on the CPU in fp32; the tokenizer, the references' resampling and codes and the codec's decoding are identical too. Both stack cases (English and Chinese cloning) are identical sample for sample; two more cases load each implementation's export in the other, identical too. The contract suite passes (6 tests).`]}),`
`,(0,n.jsx)(t.h2,{id:`limitations`,children:`Limitations`}),`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsx)(t.li,{children:`About 10 GB of GPU memory to run the model whole (S2 Pro); on a CPU it runs in fp32 and is slow.`}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.code,{children:`normalize`}),` and `,(0,n.jsx)(t.code,{children:`repetition_penalty`}),` have no effect (as upstream), and top-k cannot be changed.`]}),`
`,(0,n.jsx)(t.li,{children:`Results are under the Fish Audio Research License: not for commercial use, and not for training other engines.`}),`
`]}),`
`,(0,n.jsx)(t.h2,{id:`drama-3`,children:`Drama 3`}),`
`,(0,n.jsxs)(t.p,{children:[`Variant `,(0,n.jsx)(t.code,{children:`drama3`}),`, catalogue model `,(0,n.jsx)(t.code,{children:`fishspeech/drama-3`}),` (fishaudio/drama-3 at 78e5ab79, 41.5 GB: the weights with the experts in block FP8, and S2's `,(0,n.jsx)(t.code,{children:`codec.pth`}),`, byte for byte the same file). Ported from fish-speech 0f8a12e8 (`,(0,n.jsx)(t.code,{children:`fish_speech/models/text2semantic/fish_omni`}),` and `,(0,n.jsx)(t.code,{children:`generate_long_drama3`}),`), as `,(0,n.jsx)(t.code,{children:`mizuoto_fishspeech/drama3`}),`. It clones from one to four clips (each with its transcript), speaks without a reference in a voice of its own, takes inline directions (`,(0,n.jsx)(t.code,{children:`[whispering]`}),`, `,(0,n.jsx)(t.code,{children:`[laughing]`}),`, `,(0,n.jsx)(t.code,{children:`<whisper>…</whisper>`}),`) and up to sixteen speakers (`,(0,n.jsx)(t.code,{children:`<|speaker:0|>`}),`…`,(0,n.jsx)(t.code,{children:`<|speaker:15|>`}),`; a reference's transcript may start with its speaker's tag). Licence: the Fish Audio Community License 1.0, the variant's own (`,(0,n.jsx)(t.code,{children:`variants.drama3.licence`}),`); the engine's acceptance covers both licences, and its outputs are tagged `,(0,n.jsx)(t.code,{children:`fish-audio-community`}),`.`]}),`
`,(0,n.jsx)(t.h3,{id:`how-it-works-1`,children:`How it works`}),`
`,(0,n.jsxs)(t.table,{children:[(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{children:`Module`}),(0,n.jsx)(t.th,{children:`What it is`})]})}),(0,n.jsxs)(t.tbody,{children:[(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/config.py`})}),(0,n.jsxs)(t.td,{children:[(0,n.jsx)(t.code,{children:`config.json`}),`: the backbone's text config, the tower's, the semantic band, checked as upstream checks them`]})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/layers.py`})}),(0,n.jsx)(t.td,{children:`Zero-centred RMSNorm, partial RoPE (halves), gated softmax attention, Gated DeltaNet (a causal depthwise convolution, then the gated delta rule: by chunks of 64 for a prompt, token by token after)`})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/moe.py`})}),(0,n.jsx)(t.td,{children:`256 routed experts a layer (8 per token) and a gated shared expert; the experts stacked, kept in FP8, streamed by the row`})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/backbone.py`})}),(0,n.jsxs)(t.td,{children:[`Qwen3.5-MoE's hybrid text model (40 layers, every fourth softmax attention) and its `,(0,n.jsx)(t.code,{children:`lm_head`}),`; loading the per-expert FP8 tensors`]})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/tower.py`})}),(0,n.jsx)(t.td,{children:`The codebook tower: 4 shared and 9 residual layers attending over the frames, each residual layer's head drawing the next code; both samplers`})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/prompt.py`})}),(0,n.jsxs)(t.td,{children:[`The prompt (a chat: system turn with `,(0,n.jsx)(t.code,{children:`[Reference i]`}),` blocks, earlier chunks as finished turns, the open voice turn), text checks, long-text chunks and their history`]})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/generate.py`})}),(0,n.jsxs)(t.td,{children:[`Prefill in blocks of 128 rows (teacher-forcing the tower's caches), the decoding loop (`,(0,n.jsx)(t.code,{children:`Decoder`}),`), chunk after chunk`]})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/steps.py`})}),(0,n.jsxs)(t.td,{children:[`The decoding step as CUDA graphs around its attention calls (`,(0,n.jsx)(t.code,{children:`Stretches`}),`), its fixed tensors`]})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:(0,n.jsx)(t.code,{children:`drama3/engine.py`})}),(0,n.jsxs)(t.td,{children:[(0,n.jsx)(t.code,{children:`LoadedDrama3`}),`: S2's codec, references and operations (it subclasses `,(0,n.jsx)(t.code,{children:`LoadedFishSpeech`}),`) with the backbone and tower`]})]})]})]}),`
`,(0,n.jsxs)(t.p,{children:[`A frame is ten codes: the backbone predicts its main token (the end of the turn or a semantic token, whose place in the band is code 0) from the frames so far, each prompt row's embedding being its token's plus, for audio rows, its code 1 (scaled by 1/√2). The tower then takes the backbone's hidden state and draws codes 1–9, one residual layer per code, its first shared layer also seeing the previous frame's codes 2–9. Text is cut into chunks of about 300 UTF-8 bytes with at most three speakers each (sentence ends, then clause marks, then spaces; never inside a tag or bracket), each generated with the first chunk and the latest one in its prompt as history; `,(0,n.jsx)(t.code,{children:`single_chunk`}),` generates the whole text at once.`]}),`
`,(0,n.jsx)(t.h3,{id:`what-reproduces-upstream-1`,children:`What reproduces upstream`}),`
`,(0,n.jsxs)(t.p,{children:[`On the CPU, upstream's modules and the port give the same hidden states, logits, frames and audio, bit for bit and sample for sample (see `,(0,n.jsx)(t.a,{href:`#parity-1`,children:`Parity`}),`). In particular:`]}),`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Every operation in upstream's order`}),`: the norms in float32, the rotary tables computed per call, the delta rule's chunked form for prompts (`,(0,n.jsx)(t.code,{children:`solve_triangular`}),` per chunk) and its recurrence for steps, the GQA attention (a single query row folds each key head's query heads into rows; more rows repeat the key heads) through `,(0,n.jsx)(t.code,{children:`mizuoto.runtime.accel.attention`}),` with SDPA and a boolean mask, the tower's interleaved RoPE, its float32-output down projection for float16; in float16 the experts are dequantized in float32 and saturated to float16's range before the cast, as upstream's dense experts are.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The experts`}),`: up to 64 (token, expert) pairs in one batched matmul over the gathered experts (a decoding step), more expert by expert, summed in float32 by `,(0,n.jsx)(t.code,{children:`index_add_`}),` in the experts' order (a prompt): the two paths give different bits, so both are kept. The router's softmax and top-k in float32, the weights renormalised.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The prompt`}),`, each literal tokenised alone, references checked and tagged as upstream tags them; the chunking (upstream's tests' cases are the package's tests) and the history (the first chunk pinned, the latest one, dropped oldest first when the prompt passes 8192 rows).`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Sampling`}),` draws from the request's generator in upstream's order: per frame, the main token twice (at the request's settings over the end and the semantic band, then at 1.0, top-k 30, top-p 0.95; the second replaces the first when the first is an audio token among the last 16 main tokens), then the nine codes. A draw is `,(0,n.jsx)(t.code,{children:`argmax(p / E)`}),` with `,(0,n.jsx)(t.code,{children:`E ~ Exp(1)`}),`. The `,(0,n.jsx)(t.code,{children:`sampler`}),` option selects Fish Audio's reference sampler (`,(0,n.jsx)(t.code,{children:`reference_argmax`}),` / `,(0,n.jsx)(t.code,{children:`reference_ras`}),`, upstream's `,(0,n.jsx)(t.code,{children:`--reference-sampling`}),`): an epsilon cutoff for the main token (`,(0,n.jsx)(t.code,{children:`epsilon_cutoff`}),`, 0.001 by default), every repeated main token replaced (the end included), the codes drawn only from the codec's 1024.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Upstream's limits`}),`: at most 8192 prompt rows and 10 240 rows in all (its CUDA graphs' capacity; a chunk's frames are clamped to what is left), the defaults of Fish Audio's SDK (temperature 0.7, top-p 0.7, top-k 30, 1024 frames per chunk; `,(0,n.jsx)(t.code,{children:`max_new_tokens = 0`}),`: 600, or 2048 with `,(0,n.jsx)(t.code,{children:`single_chunk`}),`).`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The codec`}),`: S2's, its weight norm folded once in float32 before the cast to the model's precision (upstream's `,(0,n.jsx)(t.code,{children:`load_codec_model`}),` for Drama 3), decoding under autocast in that precision; references encoded in it.`]}),`
`]}),`
`,(0,n.jsx)(t.h3,{id:`cuda-graphs`,children:`CUDA graphs`}),`
`,(0,n.jsxs)(t.p,{children:[`With `,(0,n.jsx)(t.code,{children:`compute.cuda_graphs`}),` (an NVIDIA GPU holding the backbone and the tower whole: about 44 GB in bfloat16) the decoding step runs as CUDA graphs that replay the eager kernels (`,(0,n.jsx)(t.code,{children:`drama3/steps.py`}),`, `,(0,n.jsx)(t.code,{children:`generate.Decoder`}),`). A step is the tower's graphs (the output head, the frame's draws, one graph between each two of its 13 layers' attention calls), then the backbone's on that frame (one graph between each two of its 10 softmax attention layers, the Gated DeltaNet layers, the router and the experts inside them). The attention calls run eagerly between the graphs, over caches that grow by one each step, so the caches and the attention kernels are the eager code's. The step waits for the device once, for the frame's main token and whether its logits were finite.`]}),`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Fixed tensors`}),`, kept with the loaded model: the step's inputs and outputs (the last hidden state, the position, the previous frame, the last 16 main tokens padded with −1, the frame and its flags) and the Gated DeltaNet layers' states, which the graphs update in place and each request starts at zero. The attention layers' caches stay each request's own.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The sampling settings are captured as the eager code passes them`}),`, as Python numbers: CUDA divides by a number as a multiplication by its reciprocal and by a device tensor as a true division, so tensors would change bits. The tower's graphs (14 captures) are captured again when a request's temperature, top-p, top-k, sampler or cutoff differs; the backbone's are kept.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Upstream's own graphs are not ported`}),`: they capture the whole step for a few cache lengths (1024, 2048, 4096, 10 240), attending over a padded, masked cache with the settings as device tensors, which changes bits against its eager decoding.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Streamed experts decode eagerly`}),`: on a GPU smaller than the model the experts stream by the row, and which rows a step copies is learnt from the device, which a graph cannot wait for.`]}),`
`,(0,n.jsxs)(t.li,{children:[`Checked on the CPU through `,(0,n.jsx)(t.code,{children:`Graphs`}),`' contract (each stretch warmed up and captured with its state put back, then replayed): the eager audio for both samplers, several chunks, later requests and changed settings (`,(0,n.jsx)(t.code,{children:`test_the_step_as_graph_stretches_decodes_exactly_as_eagerly`}),`). On an NVIDIA GPU, `,(0,n.jsx)(t.code,{children:`test_cuda_graphs_decode_exactly_as_eagerly_on_a_gpu`}),` (bfloat16 and float16) and `,(0,n.jsx)(t.code,{children:`test_a_failed_capture_falls_back_to_the_same_audio_on_a_gpu`}),` compare graphs with eager decoding on the tiny model; they skip without one.`]}),`
`]}),`
`,(0,n.jsx)(t.h3,{id:`deviations-1`,children:`Deviations`}),`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Devices and precision.`}),` Upstream runs Drama 3 only on NVIDIA GPUs, in bfloat16 (float16 before SM80, with a float32 residual stream); its entry points refuse the CPU and float32. The port runs on every device kind, in float32 on the CPU (as S2 Pro): the reference it is checked against is upstream's modules run there in float32, unchanged.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The experts stay in FP8`}),`, the experts a call uses dequantized as it runs, as upstream does wherever its FP8 kernel does not run; upstream's other path dequantizes them all at load. Both give the same values (the tiny parity checks both against the port): 32 GB of experts instead of 64 GB in bfloat16 or 129 GB in float32. `,(0,n.jsx)(t.strong,{children:`Upstream's W8A8 kernel`}),` (Triton, SM89 and newer, which also quantizes the activations to FP8) is not ported: its results differ, so it could only come as an opt-in, and it cannot be measured here.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`No multi-GPU layer split and no cache kept between requests.`}),` Upstream spreads the layers over up to four GPUs and keeps caches sized for the largest request so far; here the model manager places the layers (streaming what does not fit) and each request has its own caches. Attention reads only the attended prefix either way.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Non-finite logits`}),` are refused, as upstream refuses them, but checked once per frame (at the frame's one wait for the device) rather than before each draw.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The audio is the chunks' audio joined`}),`, unclipped, as upstream's; S2 Pro's engine clips each batch. The variant declares `,(0,n.jsx)(t.code,{children:`long_text`}),`, so Mizuoto hands the engine the whole text and upstream's chunking and history apply (cut by Mizuoto into separate requests, the history would never cross them).`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`What Mizuoto does before any engine`}),` applies here too: the text and each reference's transcript are stripped of surrounding white space; a reference is stored in the voice library as mono 16-bit WAV (a float, 24-bit or stereo clip is converted, so its codes can differ from upstream reading the original file); one longer than 30 s is trimmed under `,(0,n.jsx)(t.code,{children:`tts.reference_policy`}),`; seeds are not negative (upstream takes the absolute value).`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Not ported`}),`: upstream's CUDA graphs for Drama 3 (they change bits; Mizuoto's replay the eager kernels, see `,(0,n.jsx)(t.a,{href:`#cuda-graphs`,children:`CUDA graphs`}),`), its fine-tuning (upstream removed its training code with Drama 3, so the LoRA method is S2 Pro's only), and "director revision" across turns (not in the open code).`]}),`
`]}),`
`,(0,n.jsx)(t.h3,{id:`memory-and-speed-1`,children:`Memory and speed`}),`
`,(0,n.jsxs)(t.p,{children:[`Handles: the backbone (`,(0,n.jsx)(t.code,{children:`kind="sequence"`}),`; each layer two units, its attention `,(0,n.jsx)(t.code,{children:`hot`}),` and its MoE, and the output head `,(0,n.jsx)(t.code,{children:`hot`}),`), the tower (`,(0,n.jsx)(t.code,{children:`sequence`}),`) and the codec. The experts stream `,(0,n.jsx)(t.strong,{children:`by the row`}),` (`,(0,n.jsx)(t.a,{href:`/docs/development-memory#units-what-streams`,children:`Development: memory`}),`): a layer whose MoE unit is not resident keeps its 256 experts in pinned host memory and each call copies the experts its tokens are routed to (a decoding step: 8 a layer, about 25 MB; a prompt block: expert by expert), so a GPU far smaller than the model runs it. Whole, the model needs about 44 GB; its dense part (attention, shared experts, embeddings and head, the tower) is about 7.5 GB in bfloat16. Working memory per request: the softmax layers' and the tower's caches for the request's rows (at most 10 240), the DeltaNet states, a prompt block's activations and the experts a step dequantizes.`]}),`
`,(0,n.jsxs)(t.p,{children:[`On the CPU, in float32 with 16 threads, a frame takes about 2.1 s, upstream's modules as long (a second of speech is 21.5 frames: some 45 s of compute); a prompt of 230 rows about 35 s. On a GPU it needs about 44 GB to hold the whole model, or its experts (30 GiB) stream from RAM; where RAM cannot hold them either, the layers' experts that do not fit are kept in files (`,(0,n.jsx)(t.code,{children:`runtime.filemap`}),`, `,(0,n.jsx)(t.a,{href:`/docs/development-memory#host-copies-and-ram`,children:`Memory`}),`). First run on a GPU, 2026-11-05: an RTX 3060 (12 GB, PCIe x4) in a machine with 31 GB of RAM, bf16: 9.1 GB on the GPU, 17.0 GB of experts in page-locked RAM, 20.7 GB in files; a warm request of 5.5–8.3 s of speech took 128–162 s (176–226 GB copied to the GPU a request, 1.4 GB/s), its two runs identical; 15–32 GiB of it read from the disk, the rest of the file-backed experts from the page cache (72–87 %); RAM never fell below 7.9 GB available.`]}),`
`,(0,n.jsx)(t.p,{children:`A random model with the real one's shapes but 8 experts did run, on an RTX 3060 (2026-11-03, torch 2.8, bf16, 8.5 GB on the device). Every token still uses 8 experts, so a decoding step does the real model's work.`}),`
`,(0,n.jsxs)(t.ul,{children:[`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Speed:`}),` 150 frames took 19.2 s eagerly and 16.3 s with CUDA graphs, ×1.18 (128 → 109 ms a frame), identical audio.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`Graphed frames:`}),` about 7,250 kernels each, the device busy 97 % of the time.`]}),`
`,(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:`The tiny test model:`}),` ×2.1 (1.56 → 0.74 s a request), identical too.`]}),`
`]}),`
`,(0,n.jsx)(t.h3,{id:`parity-1`,children:`Parity`}),`
`,(0,n.jsxs)(t.p,{children:[`Against upstream's own modules (fish-speech 0f8a12e8) on the CPU in float32, the same seed and thread count, with the real model (2026-11-01; workspace `,(0,n.jsx)(t.code,{children:`experiment/fish-drama3`}),`, `,(0,n.jsx)(t.code,{children:`scripts/real_upstream.py`}),`, `,(0,n.jsx)(t.code,{children:`real_native.py`}),`, `,(0,n.jsx)(t.code,{children:`real_compare.py`}),`): seven cases, the reference clips' codes, every chunk's codes and the audio `,(0,n.jsx)(t.strong,{children:`identical`}),` sample for sample: English and Chinese cloning, no reference, inline tags (`,(0,n.jsx)(t.code,{children:`[laughing]`}),`, `,(0,n.jsx)(t.code,{children:`[whispering]`}),`), a two-speaker dialogue with two references, the reference sampler (`,(0,n.jsx)(t.code,{children:`reference_ras`}),`, cutoff 0.002), and a long text generated as two chunks with history (542 frames, 25 s). Upstream repeated itself exactly before being compared. Upstream ran as its `,(0,n.jsx)(t.code,{children:`TTSInferenceEngine`}),` runs a request (references through its loader and codec, `,(0,n.jsx)(t.code,{children:`set_seed`}),`, `,(0,n.jsx)(t.code,{children:`generate_long_drama3`}),`, its codec's decoding), the port as the server runs it (`,(0,n.jsx)(t.code,{children:`synthesize`}),`). On a tiny random model (`,(0,n.jsx)(t.code,{children:`scripts/tiny_parity.py`}),`) twelve cases more (no cap on top-k, top-k 10 at temperature 1.2, single chunk, `,(0,n.jsx)(t.code,{children:`max_new_tokens = 0`}),`, Chinese with paired tags…) are identical in float32 and bfloat16, against upstream's FP8 experts and its dequantized ones, with the backbone's hidden states and logits bit for bit.`]}),`
`,(0,n.jsxs)(t.p,{children:[`A source review against upstream found Mizuoto cutting Drama 3's long text itself (fixed: the variant declares `,(0,n.jsx)(t.code,{children:`long_text`}),`) and float16's experts unclamped (fixed), and the request-level differences listed under Deviations.`]})]})}function s(e={}){let{wrapper:t}=e.components||{};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(o,{...e})}):o(e)}export{s as default,r as frontmatter,i as structuredData,a as toc};